<template>
  <div class="berry-backdrop" @keydown.stop="keys" @keyup.stop>
    <section ref="dialog" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="berry-title" class="berry-panel" :class="{mutator}">
      <header><housing-item-icon :item-key="mutator?'berry_mutator':payload.slots===3?'berry_planter':'berry_pot'"/><div><small>CHEZ TOI · ATELIER DES BAIES</small><h2 id="berry-title">{{mutator?'Mutateur de baies':'Tes cultures'}}</h2></div><button aria-label="Fermer" :disabled="busy" @click="close">×</button></header>
      <nav v-if="mutator" aria-label="Atelier"><button :aria-pressed="tab==='mix'" @click="tab='mix'">Mutation</button><button :aria-pressed="tab==='recipes'" @click="tab='recipes'">Carnet · {{payload.recipes.length}}</button></nav>
      <div class="berry-body">
        <template v-if="!mutator">
          <p class="berry-intro">Une baie, 50 Éclats fissurés et vingt minutes. Chaque plant pousse à son rythme, même en ton absence.</p>
          <div class="berry-crops">
            <button v-for="(crop,index) in crops" :key="index" :aria-pressed="slot===index" class="berry-crop" :class="crop.stage" @click="slot=index">
              <span class="crop-number">{{index+1}}</span><span class="crop-sprite" :style="growthStyle(crop)"/><b>{{crop.stage==='empty'?'Terre libre':label(crop.berryKey)}}</b><small>{{crop.stage==='mature'?'Prête à récolter':crop.stage==='empty'?'Une nouvelle plantation ?':remaining(crop.remainingMs)}}</small><progress v-if="crop.stage!=='empty'" :value="1200000-crop.remainingMs" max="1200000"/>
            </button>
          </div>
          <div v-if="active.stage==='empty'" class="berry-planting">
            <div class="ingredient-socket" data-berry-drop="0" :class="{filled:chosen[0]}" @dragover.prevent @drop.prevent="drop($event,0)" @click="focusIngredient=0"><berry-icon v-if="chosen[0]" :item-key="chosen[0]"/><span>{{chosen[0]?label(chosen[0]):'Dépose une baie classique'}}</span></div>
            <span class="plus">+</span><button class="crystal-deposit" :aria-pressed="crystals" :disabled="shards<50" @click="!pending&&(crystals=!crystals)"><span aria-hidden="true">◈</span><b>50 Éclats fissurés</b><small>{{crystals?'Cristaux déposés':shards<50?'Stock insuffisant':'Déposer les cristaux'}}</small></button>
          </div>
          <div v-else class="plant-detail"><b>{{active.stage==='mature'?'Ta baie a mûri.':'La corruption prend racine.'}}</b><p>{{active.stage==='mature'?'La récolte libère cet emplacement.':'Tu peux partir : la croissance continuera sans toi.'}}</p><button v-if="active.stage==='mature'" class="berry-primary" :disabled="busy||pending" @click="act('harvest',{slot})">Récolter {{label(active.berryKey)}} (Corrompue)</button></div>
        </template>
        <template v-else-if="tab==='mix'">
          <p class="berry-intro">Trois baies corrompues, une nouvelle mutation. Un mélange garde ses résultats possibles ; la rareté reste une surprise à chaque tentative.</p>
          <div class="mutator-tray" :class="{working:busy}"><div v-for="(_,index) in chosen" :key="index" class="ingredient-socket" :class="{filled:chosen[index],focused:focusIngredient===index}" :data-berry-drop="index" @dragover.prevent @drop.prevent="drop($event,index)" @click="focusIngredient=index"><button v-if="chosen[index]" aria-label="Retirer cette baie" class="remove" :disabled="busy" @click.stop="!pending&&$set(chosen,index,null)">×</button><berry-icon v-if="chosen[index]" :item-key="chosen[index]"/><span>{{chosen[index]?label(chosen[index]):'Baie '+(index+1)}}</span></div></div>
          <div class="mutation-odds"><span class="failed">20 % ratée</span><span class="common">50 % commune</span><span class="rare">25 % rare</span><span class="legendary">5 % légendaire</span></div>
          <p class="berry-permanent">Une baie mutée peut être tenue par tout Pokémon. Elle est consommée définitivement à son entrée en combat, dans tous les modes ; ses effets cessent au retrait.</p>
          <div v-if="result" :key="result.key+'-'+resultCount" class="mutation-result" :class="result.rarity" role="status"><berry-icon :item-key="result.itemKey"/><div><small>{{rarities[result.rarity]}}</small><h3>{{label(result.itemKey)}}</h3><p>{{definition(result.itemKey).description}}</p></div></div>
        </template>
        <div v-else class="recipe-register"><p v-if="!payload.recipes.length" class="berry-empty">Ton carnet est encore vierge. Essaie un premier mélange pour y noter ses résultats possibles.</p><article v-for="r in payload.recipes" :key="r.key"><h3>{{r.name}} <small>{{r.attempts}} essai{{r.attempts>1?'s':''}}</small></h3><div class="recipe-ingredients"><span v-for="(key,i) in r.ingredients" :key="i"><berry-icon :item-key="key"/><small>{{label(key)}}</small></span><button :disabled="busy" @click="reuse(r)">Refaire →</button></div><div class="recipe-outcomes"><div v-for="rarity in ['common','rare','legendary']" :key="rarity" :class="rarity"><berry-icon :item-key="r.results[rarity]"/><b>{{label(r.results[rarity])}}</b><small>{{definition(r.results[rarity]).description}}</small></div></div></article></div>
        <section v-if="(!mutator&&active.stage==='empty')||(mutator&&tab==='mix')" class="berry-stock"><div class="stock-heading"><h3>{{mutator?'Baies corrompues':'Tes baies classiques'}}</h3><span>{{mutator?'Choisis un emplacement, puis une baie':'Glisse une baie ou touche son nom'}}</span></div><input v-model="query" type="search" placeholder="Rechercher une baie…" aria-label="Rechercher une baie"/><p v-if="!stock.length" class="berry-empty">{{mutator?'Récolte des baies corrompues dans tes pots pour commencer.':'Il te faut une baie classique pour planter.'}}</p><div class="berry-stock-list"><button v-for="i in stock" :key="i.key" :disabled="busy||available(i.key)<1" :title="i.description" @click="choose(i.key)"><span class="berry-drag" draggable="true" @dragstart="drag($event,i.key)" @pointerdown="pointerStart($event,i.key)"><berry-icon :item-key="i.key"/></span><span><b>{{i.name}}</b><small>× {{available(i.key)}}</small></span></button></div></section>
      </div>
      <p v-if="error" class="berry-error" role="alert">{{error}}</p><p v-if="localError" class="berry-error" role="alert">{{localError}}</p>
      <footer><span>{{mutator?'Trois ingrédients consommés par tentative.':shards.toLocaleString('fr-FR')+' Éclats fissurés en réserve'}}</span><button v-if="pending" :disabled="busy" @click="retry">Vérifier l’enregistrement</button><button v-else-if="mutator&&tab==='mix'" class="berry-primary" :disabled="busy||!canMutate" @click="act('mutate',{ingredients:[...chosen]})">{{busy?'Mutation en cours…':'Lancer la mutation'}}</button><button v-else-if="!mutator&&active.stage==='empty'" class="berry-primary" :disabled="busy||!chosen[0]||!crystals" @click="act('plant',{slot,berryKey:chosen[0]})">Planter · 20 min</button><button v-else @click="close">Fermer</button></footer>
    </section>
  </div>
</template>
<script>
import BerryIcon from '../menu/BerryIcon.vue';
import HousingItemIcon from './HousingItemIcon.vue';
import definitions from '@/data/berryItems.json';
const catalog=new Map(definitions.map(i=>[i.key,i]));
export default{
 components:{BerryIcon,HousingItemIcon},props:{payload:Object,busy:Boolean,error:String,command:Function},
 data:()=>({slot:0,chosen:[null,null,null],crystals:false,tab:'mix',query:'',focusIngredient:0,clock:Date.now(),pending:null,result:null,resultCount:0,localError:'',rarities:{failed:'Mutation ratée',common:'Mutation commune',rare:'Mutation rare',legendary:'Mutation légendaire'}}),
 computed:{canMutate(){const counts=new Map();for(const k of this.chosen){if(!k)return false;counts.set(k,(counts.get(k)||0)+1);}return [...counts].every(([k,n])=>(this.payload.items.find(i=>i.key===k)?.quantity||0)>=n);},mutator(){return this.payload.kind==='mutator';},now(){return this.clock+(this.payload.serverNow-this._receivedAt||0);},crops(){return Array.from({length:this.payload.slots||1},(_,slot)=>{const c=this.payload.home.crops?.find(x=>x.furnitureId===this.payload.furnitureId&&x.slot===slot);if(!c)return{stage:'empty'};const elapsed=Math.max(0,this.now-c.plantedAt);return{...c,stage:elapsed>=1200000?'mature':elapsed>=300000?'sprout':'seed',remainingMs:Math.max(0,1200000-elapsed)};});},active(){return this.crops[this.slot]||{stage:'empty'};},shards(){return this.payload.items.find(i=>i.key==='crystal_shard')?.quantity||0;},stock(){return this.payload.items.filter(i=>(this.mutator?i.berryKind==='ingredient':catalog.get(i.key)?.classic)&&i.name.toLocaleLowerCase().includes(this.query.toLocaleLowerCase()));}},
 watch:{'payload.serverNow'(){this._receivedAt=Date.now();}},
 mounted(){this._receivedAt=Date.now();this._timer=setInterval(()=>this.clock=Date.now(),1000);this.$refs.dialog.focus({preventScroll:true});},beforeDestroy(){clearInterval(this._timer);this.clearPointer?.();},
 methods:{definition:k=>catalog.get(k)||{},label:k=>catalog.get(k)?.name||k,remaining(ms){const n=Math.ceil(ms/1000);return Math.floor(n/60)+' min '+String(n%60).padStart(2,'0')+' s';},growthStyle(c){const index={seed:0,sprout:1,mature:2}[c.stage];return index===undefined?{}:{backgroundImage:'url('+require('@/assets/berries/growth-v1.png')+')',backgroundPosition:(-index*64)+'px 0'};},available(k){return Math.max(0,(this.payload.items.find(x=>x.key===k)?.quantity||0)-this.chosen.filter(x=>x===k).length);},choose(k,index=this.mutator?this.focusIngredient:0){if(this.pending)return;if(this.available(k)<1&&this.chosen[index]!==k)return;this.$set(this.chosen,index,k);if(this.mutator)this.focusIngredient=this.chosen.findIndex(x=>!x);if(this.focusIngredient<0)this.focusIngredient=0;},drag(e,k){e.dataTransfer.setData('text/plain',k);},drop(e,index){const key=e.dataTransfer.getData('text/plain');if(this.stock.some(i=>i.key===key))this.choose(key,index);},pointerStart(e,key){if(e.button!==0&&e.pointerType==='mouse')return;const start={x:e.clientX,y:e.clientY},move=ev=>{if(Math.hypot(ev.clientX-start.x,ev.clientY-start.y)>8)ev.preventDefault();},up=ev=>{const node=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-berry-drop]');if(node)this.choose(key,Number(node.dataset.berryDrop));this.clearPointer();};this.clearPointer?.();this.clearPointer=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);};window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up);},async act(name,data){this.localError='';if(!this.pending)this.pending={name,data:{...data,floor:this.payload.floor,furnitureId:this.payload.furnitureId,revision:this.payload.home.revision,requestId:crypto.randomUUID()}};await this.retry();},async retry(){const request=this.pending;if(!request)return;const r=await this.command(request.name,request.data);if(!r)return;if(r.success===false){if(!r.retryable)this.pending=null;return;}this.pending=null;this.chosen=[null,null,null];this.crystals=false;if(r.receipt?.mutation){this.result=r.receipt.mutation;this.resultCount++;}},reuse(r){if(this.pending)return;this.chosen=[...r.ingredients];this.tab='mix';this.query='';},keys(e){if(e.key==='Escape')this.close();},close(){if(!this.busy)this.$emit('close');}}
};
</script>
